package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.security.cert.CRL;
import java.security.cert.X509CRL;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import org.mockito.Mockito;

public class ExpiredCrlTest extends CrlKeystoreServiceTestBase {

    private static final String VALID_ISSUER = "CN=Valid CA";
    private static final String EXPIRED_ISSUER = "CN=Expired CA";
    private static final long CRL_UPDATE_TIMEOUT_MS = 60_000;

    private final List<String> crlUrls = new ArrayList<>();
    private final Map<String, Object> crlOptions = new HashMap<>();
    private Date nextUpdate;
    private KuraException addCrlError;

    @Test
    public void expiredDownloadedCrlFailsVerificationWhenRejectionIsEnabled() throws Exception {
        givenExpiredCrlRejectionEnabled();
        givenPublishedCrl("valid.crl", VALID_ISSUER, Instant.now().plusSeconds(3600));
        givenPublishedCrl("expired.crl", EXPIRED_ISSUER, Instant.now().minusSeconds(3600));
        givenKeystoreServiceDownloadingThePublishedCrls();

        whenCrlCacheIsUpdated();

        thenServedCrlIssuersAre(VALID_ISSUER);
    }

    @Test
    public void expiredDownloadedCrlIsStoredByDefault() throws Exception {
        givenPublishedCrl("valid.crl", VALID_ISSUER, Instant.now().plusSeconds(3600));
        givenPublishedCrl("expired.crl", EXPIRED_ISSUER, Instant.now().minusSeconds(3600));
        givenKeystoreServiceDownloadingThePublishedCrls();

        whenCrlCacheIsUpdated();

        thenServedCrlIssuersAre(VALID_ISSUER, EXPIRED_ISSUER);
    }

    @Test
    public void storedCrlIsNoLongerServedOnceExpiredWhenRejectionIsEnabled() throws Exception {
        givenExpiredCrlRejectionEnabled();
        givenPublishedCrl("valid.crl", VALID_ISSUER, Instant.now().plusSeconds(5));
        givenKeystoreServiceDownloadingThePublishedCrls();
        givenCrlCacheUpdatedWith(VALID_ISSUER);

        whenStoredCrlExpires();

        thenServedCrlIssuersAre();
    }

    @Test
    public void storedCrlIsStillServedOnceExpiredByDefault() throws Exception {
        givenPublishedCrl("valid.crl", VALID_ISSUER, Instant.now().plusSeconds(5));
        givenKeystoreServiceDownloadingThePublishedCrls();
        givenCrlCacheUpdatedWith(VALID_ISSUER);

        whenStoredCrlExpires();

        thenServedCrlIssuersAre(VALID_ISSUER);
    }

    @Test
    public void expiredCrlAddedToTheKeystoreIsRejectedWhenRejectionIsEnabled() throws Exception {
        givenExpiredCrlRejectionEnabled();
        givenKeystoreServiceWithCrlManagement(this.crlOptions);

        whenCrlIsAdded(EXPIRED_ISSUER, Instant.now().minusSeconds(3600));

        thenCrlIsRejectedAsBadRequest();
        thenServedCrlIssuersAre();
    }

    @Test
    public void expiredCrlAddedToTheKeystoreIsKeptByDefault() throws Exception {
        givenKeystoreServiceWithCrlManagement(this.crlOptions);

        whenCrlIsAdded(EXPIRED_ISSUER, Instant.now().minusSeconds(3600));

        thenNoErrorIsReported();
        thenServedCrlIssuersAre(EXPIRED_ISSUER);
    }

    private void givenExpiredCrlRejectionEnabled() {
        this.crlOptions.put("crl.reject.expired", true);
    }

    private void givenPublishedCrl(final String fileName, final String issuer, final Instant crlNextUpdate)
            throws Exception {
        final X509CRL crl = newCrl(issuer, Date.from(Instant.now().minusSeconds(7200)), Date.from(crlNextUpdate));
        this.nextUpdate = crl.getNextUpdate();
        this.crlUrls.add(writeCrlFile(fileName, crl).toURI().toString());
    }

    private void givenKeystoreServiceDownloadingThePublishedCrls() throws Exception {
        this.crlOptions.put("crl.urls", this.crlUrls.toArray(new String[0]));
        this.crlOptions.put("verify.crl", false);

        givenKeystoreServiceWithCrlManagement(this.crlOptions);
    }

    private void givenCrlCacheUpdatedWith(final String issuer) throws Exception {
        whenCrlCacheIsUpdated();
        thenServedCrlIssuersAre(issuer);
    }

    private void whenCrlCacheIsUpdated() {
        Mockito.verify(this.eventAdmin, Mockito.timeout(CRL_UPDATE_TIMEOUT_MS)).postEvent(ArgumentMatchers.any());
    }

    private void whenStoredCrlExpires() throws InterruptedException {
        final long remainingMs = this.nextUpdate.getTime() - System.currentTimeMillis();

        Thread.sleep(Math.max(0, remainingMs) + 1500);
    }

    private void whenCrlIsAdded(final String issuer, final Instant crlNextUpdate) throws Exception {
        final X509CRL crl = newCrl(issuer, Date.from(Instant.now().minusSeconds(7200)), Date.from(crlNextUpdate));

        try {
            this.keystoreService.addCRL(crl);
        } catch (final KuraException e) {
            this.addCrlError = e;
        }
    }

    private void thenServedCrlIssuersAre(final String... expectedIssuers) throws Exception {
        final Set<String> expected = Set.of(expectedIssuers);

        assertEquals(expected, issuersOf(this.keystoreService.getCRLs()));
        assertEquals(expected, issuersOf(this.keystoreService.getCRLStore().getCRLs(null)));
    }

    private void thenCrlIsRejectedAsBadRequest() {
        assertTrue("expected the CRL to be rejected", this.addCrlError != null);
        assertEquals(KuraErrorCode.BAD_REQUEST, this.addCrlError.getCode());
        assertTrue(this.addCrlError.getMessage(), this.addCrlError.getMessage().contains("expired"));
    }

    private void thenNoErrorIsReported() {
        assertNull(this.addCrlError);
    }

    private static Set<String> issuersOf(final Collection<? extends CRL> crls) {
        return crls.stream().map(c -> ((X509CRL) c).getIssuerX500Principal().getName())
                .collect(Collectors.toSet());
    }
}
